public class Course {
    String courseName;

    public Course(String courseName) {
        this.courseName = courseName;
    }

    @Override
    public String toString() {
        return courseName;
    }
}

ArrayList<Course> courseList = new ArrayList<>();
courseList.add(new Course("Java"));
courseList.add(new Course("Hibernate"));
courseList.add(new Course("AngularJS"));

items:
Using for loop: for (int index = 0; index < courseList.size(); index++) {
    System.out.println(courseList.get(index));
}

Using enhanced for loop (for-each): for (Course c : courseList) {
    System.out.println(c);
}

Using Iterator: Iterator<Course> courseIterator = courseList.iterator();
while (courseIterator.hasNext()) {
    Course c = courseIterator.next();
    System.out.println(c);
}

