numberSet.add(24);
numberSet.add(12); // Duplicate ignored
System.out.println(numberSet); // Output: [12, 24]

items:
Using Iterator: Iterator<Integer> iter = numberSet.iterator();
while (iter.hasNext()) {
    System.out.println(iter.next());
}

Using enhanced for loop: for (Integer num : numberSet) {
    System.out.println(num);
}

TreeSet Example: Set<String> courseSet = new TreeSet<>();
courseSet.add("Java");
courseSet.add("Hibernate");
courseSet.add("AngularJS");

for (String s : courseSet) {
    System.out.println(s);
}

Using keySet(): Set<Integer> keys = studentCourses.keySet();
for (Integer key : keys) {
    System.out.println(studentCourses.get(key));
}

Using values(): for (Set<Course> courses : studentCourses.values()) {
    System.out.println(courses);
}

Using entrySet(): Set<Map.Entry<Integer, Set<Course>>> entries = studentCourses.entrySet();
for (Map.Entry<Integer, Set<Course>> entry : entries) {
    System.out.println(entry.getKey() + " => " + entry.getValue());
}

